select case when year(hire_date) < 2024 then 'before_2024' when year(hire_date) = 2024 then '2024' else 'after_2024' end as hire_cohort, sum(salary) as total_salary, count(*) as cnt, round(sum(salary) * 100.0 / sum(sum(salary)) over (), 2) as pct_of_total from employees group by case when year(hire_date) < 2024 then 'before_2024' when year(hire_date) = 2024 then '2024' else 'after_2024' end order by pct_of_total desc;
